<?phpnamespace app\store\controller\statistics;use app\store\controller\Controller;use app\store\model\PaybillLog as PaybillLogModel;use think\facade\View;/** * 买单记录控制器 */class Paybill extends Controller{    /**     * 列表     */    public function logs()    {        $model = new PaybillLogModel;        $list = $model->getList();        return View::fetch('logs', compact('list'));    }}